const LV=()=>(state.nf&&DATA.levelsNF?DATA.levelsNF:DATA.levels)[state.lv];
// ---- core logic (shared by page and node test)
// 10/12 加工施設の式(実測): 基礎効率は「能力Lv−推奨Lv」で 0→100%、+1→300%、+2→400%、+3→500%(性格一致で×1.2)。1個の秒数=作業量÷(効率/100)
// 能力Lv4も同じ式(11/6 ユーザー実測: 推奨Lv2で480%・推奨Lv3で360%、性格一致)。推奨Lvより低いアニモは加工に使わない(ユーザー決定)
const PB={0:100,1:300,2:400,3:500};
function canDo(rec,L){return Math.min(L,4)>=rec;}
function effSec(work,rec,L,match=true){const d=Math.min(Math.min(L,4)-rec,3); /* 11/6 ユーザー実測: 能力Lv4 も同じ式(推奨Lv2で480%・推奨Lv3で360%、性格一致) */ if(d<0) return Infinity; return work*100/(PB[d]*(match?1.2:1.0));}
const REL=['闇','風','火','クラフト','水','調香','草','土'];
const FIELD=['草','土','水','闇'];
function labelOf(a){return a.form==='基本'?a.name:`${a.name}(${a.form})`;}
function buildGroups(animo,opt){
  const G=new Map();
  for(const a of animo){
    const sp=(a.form==='虹色');   // 10/12 シーズン限定は普通のアニモと同じ扱い
    if(sp&&!opt.special) continue;
    if(!REL.some(x=>a.ab[x])) continue;
    const hl=a.ab['運搬']||0, k=REL.map(x=>a.ab[x]||0).join(',')+'|'+(hl>=2?2:hl?1:0)+'|'+(sp?1:0);   // 11/4 運搬Lv.2以上を分ける
    if(!G.has(k)) G.set(k,{members:[],species:[],ab:a.ab,carry:!!a.ab['運搬'],hv:hl>=2,special:sp});
    const g=G.get(k); g.members.push(labelOf(a)); if(!g.species.includes(a.name)) g.species.push(a.name);
  }
  const arr=[...G.values()];
  arr.forEach(g=>{g.key=g.members.join('／'); g.score=REL.reduce((s,x)=>s+(g.ab[x]||0),0);});
  arr.sort((a,b)=>(a.special-b.special)||(b.score-a.score)||a.key.localeCompare(b.key));
  arr.forEach((g,i)=>g.id=i);
  return arr;
}
// 10/12 アニモ1体の時間の使い方: 加工に使える上限(専任9割・運搬持ち6割・草土水闇持ち5割・両方4割)
const isFarm=g=>['草','闇','土','水'].some(k=>g.ab[k]);
function base(g){const f=isFarm(g); return g.carry?(f?0.4:0.6):(f?0.5:0.9);}
// 運搬の戦力として数える割合(加工に使わなかった残りに掛ける。両方持ちは畑・森の作業があるので7割)
function haulf(g){return g.hv?(isFarm(g)?0.7:1.0):0;}   // 11/4 ユーザー: 運搬の戦力はLv.2以上だけ数える
// 草・土・水・闇は各3体以上(土・草は運搬なしを1体ずつ)。運搬の戦力はLv.15 MAXで3.0体分(配置ごとの値は data の haul)
const EXTRA={'木工台':1.2,'煙突鍛造炉':1.1};
const MARGIN=1.0, FIELDMIN=3, NCFIELD=['草','土'], HAULDEF=3.0;
function margin(g){return MARGIN;}
const num=x=>(+x).toFixed(6);
function solveCore(fc,optData,groups,caps,highs,pref,match=true,spmax=null,FM=1){
  const agg={};
  // 10/17 外から入る木材・鉱砂(成長剤・デイリー注文など)の分を見込む(ユーザー決定: 木工台1.2倍・煙突鍛造炉1.1倍)
  for(const [ab,fac,d,w,rec] of optData.tasks){const k=fac+'|'+rec; (agg[k]=agg[k]||{ab,fac,rec,work:0}).work+=d*w*(EXTRA[fac]||1);}
  const T=Object.values(agg);
  const capOf=g=>Math.min(caps[g.key]??6,6);
  const farm=g=>['草','闇','土','水'].some(k=>g.ab[k]);
  let cand=groups.filter(g=>capOf(g)>0 && (T.some(t=>g.ab[t.ab])||FIELD.some(f=>g.ab[f])||g.carry));
  const relAb=new Set([...T.map(t=>t.ab),...FIELD]);
  const useG=cand.filter(g=>!cand.some(h=>h!==g && (!h.special||g.special) && h.carry===g.carry && h.hv===g.hv && farm(h)===farm(g) && capOf(h)>=6 &&
      REL.every(k=>(h.ab[k]||0)>=(g.ab[k]||0)) && (REL.some(k=>(h.ab[k]||0)>(g.ab[k]||0)) || h.id<g.id)));
  const obj=[], st=[], bounds=[], gen=[];
  const C={}; const add=(c,term)=>{(C[c]=C[c]||[]).push(term);};
  for(const g of useG){
    const n='n'+g.id, b=base(g);
    const hf=haulf(g);
    // 体数が同じなら、加工の空き時間と運搬の戦力が多い組み合わせを優先。11/9 ユーザー: 体数が減らなくても少しでも効率が上がるなら虹色を入れる(効率が全く同じときだけ虹色の少ないほう)
    obj.push(`${num(100-(b+hf)+(g.special?0.001:0))} ${n}`);
    if(hf) add('haul',`+ ${num(hf)} ${n}`); gen.push(n); bounds.push(`0 <= ${n} <= ${Math.min(caps[g.key]??6,6)}`);
    add('cap'+g.id,`- ${num(margin(g)*b)} ${n}`);
    for(const f of FIELD) if((g.ab[f]||0)>=2){ add('f_'+f,`+ 1 ${n}`); if(!g.carry) add('nc_'+f,`+ 1 ${n}`); }
    T.forEach((t,j)=>{const L=g.ab[t.ab]; if(!L||!canDo(t.rec,L)) return; const x=`x${g.id}_${j}`;
      add('t'+j,`+ ${num(86400/effSec(1,t.rec,Math.min(L,4),match))} ${x}`); add('cap'+g.id,`+ 1 ${x}`); add('F_'+t.fac,`+ 1 ${x}`);
      obj.push(`${num(1+hf)} ${x}`); if(hf) add('haul',`- ${num(hf)} ${x}`);});
  }
  const fn=c=>C[c]?C[c].join(' ').replace(/^\+ /,''):null;
  const R=[];
  for(const g of useG){R.push(` cap${g.id}: ${fn('cap'+g.id)} <= 0`);}
  const H=optData.haul??HAULDEF; if(H>0){ if(!C['haul']) return {ok:false,why:'運搬を持つアニモがいません',haulFail:true}; R.push(` haul: ${fn('haul')} >= ${num(H)}`); }
  if(spmax!=null){const sp=useG.filter(g=>g.special).map(g=>'n'+g.id); if(sp.length) R.push(` spmax: ${sp.join(' + ')} <= ${spmax}`);}
  for(const f of FIELD){ if(!C['f_'+f]) return {ok:false,why:`${f}を持つアニモがいません`}; R.push(` f_${f}: ${fn('f_'+f)} >= ${FIELDMIN}`);}
  for(const f of NCFIELD){ if(C['nc_'+f]) R.push(` nc_${f}: ${fn('nc_'+f)} >= 1`); }
  T.forEach((t,j)=>{ if(!C['t'+j]) R.push(` t${j}: 0 x_dummy >= 1`); else R.push(` t${j}: ${fn('t'+j)} >= ${num(t.work)}`);});
  const facs=[...new Set(T.map(t=>t.fac))]; const fcx=f=>Math.max(0,(fc[f]||1)-((optData.pwfac||{})[f]||0))*1.01;   // 10/14: 1日の個数の切り上げで100%をわずかに超える分(0.1%程度)は許す facs.forEach((f,i)=>{if(C['F_'+f]) R.push(` F${i}: ${fn('F_'+f)} <= ${num(fcx(f)*FM)}`);});
  const lp=`Minimize\n obj: ${obj.join(' + ')}\nSubject To\n${R.join('\n')}\nBounds\n${bounds.join('\n')}\nGeneral\n ${gen.join(' ')}\nEnd\n`;
  let r; try{ r=highs.solve(lp,{time_limit:10}); }catch(e){ return {ok:false,why:'計算できませんでした'}; }
  if(!/Optimal|Time limit/i.test(r.Status) || !r.Columns){
    const over=[];
    for(const f of facs){ let need=0; for(const t of T){ if(t.fac!==f) continue; const Lmax=Math.max(0,...useG.map(g=>g.ab[t.ab]||0)); if(!Lmax||!canDo(t.rec,Lmax)){need=Infinity;break;} need+=t.work*effSec(1,t.rec,Math.min(Lmax,4),match)/86400; } if(need>fcx(f)) over.push(f); }
    if(over.length) return {ok:false,why:`${over.join('・')}の台数では加工が間に合いません${match?'':'(性格が合わないと遅くなるため)'}`};
    return {ok:false,why:'この条件では組めません',haulFail:true};
  }
  const v=k=>(r.Columns[k]?r.Columns[k].Primal:0);
  const team=[];
  for(const g of useG){const n=Math.round(v('n'+g.id)); if(!n) continue;
    const w=0, cap=n*base(g); const use={};
    const perFac={};
    T.forEach((t,j)=>{const x=v(`x${g.id}_${j}`); if(x>1e-6){perFac[t.fac]=(perFac[t.fac]||0)+x; (use[t.ab]=use[t.ab]||{x:0,f:[]}).x+=x; if(!use[t.ab].f.includes(t.fac)) use[t.ab].f.push(t.fac);}});
    team.push({g,n,perFac,water:Math.round(w/n*100),use:Object.entries(use).filter(([a,u])=>u.x/n>=0.03).sort((a,b)=>b[1].x-a[1].x).map(([a,u])=>[a,Math.round(u.x/n*100),u.f])});}
  return {ok:true,team,total:team.reduce((s,t)=>s+t.n,0),status:r.Status,ncMissing:NCFIELD.filter(f=>!C['nc_'+f])};
}
// 運搬の戦力が足りずに組めないときは、運搬の条件を外して組み、足りない分を知らせる
function solveTeam(fc,optData,groups,caps,highs,pref,match=true,spmax=null){
  const r=solveCore(fc,optData,groups,caps,highs,pref,match,spmax);
  if(r.ok||!r.haulFail) return r;
  const H=optData.haul??HAULDEF;
  const r2=solveCore(fc,Object.assign({},optData,{haul:0}),groups,caps,highs,pref,match,spmax);
  if(!r2.ok) return r;
  let got=0; for(const t of r2.team){const x=Object.values(t.perFac).reduce((a,b)=>a+b,0); got+=haulf(t.g)*(t.n-x);}
  r2.haulShort={need:H,got:Math.max(0,got)}; return r2;
}
if(typeof module!=='undefined') module.exports={buildGroups,solveTeam,base,haulf,labelOf,margin};

